@startuml

class Student {
  + studentID : int
  + birthDate : date
  + birthCity : string
  + birthRegion : string
  + enrollmentYear : int
}

class Professor {
  + name : string
  + birthDate : date
  + birthCity : string
}

class Faculty {
  + name : string
  + type : string
}

class Course {
  + code : string
  + lectureHours : int
}

class Exam {
  + grade : float
}

Student "1" -- "*" StudentEnrollment : enrolledIn
StudentEnrollment "*" -- "1" Faculty

Student "1" -- "*" Exam : passes
Exam "*" -- "1" Course

Professor "*" -- "*" Course : teaches

Course "*" -- "1" Faculty

@enduml

